local OysterFarmer = {}
local PRODUCTS = {
    common_oyster = { name = "Navadna ostriga", oysterBedCost = 1, time = 3, cost = 18, yield = 35, happiness = 1, description = "Navadna ostriga iz ostrigarske farme." },
    pearl_oyster = { name = "Biserna ostriga", pearlOysterBedCost = 1, time = 5, cost = 50, yield = 45, prestige = 2, description = "Biserna ostriga za bisere." },
    cultivated_pearl = { name = "Gojen biser", pearlOysterBedCost = 1, time = 8, cost = 140, yield = 55, prestige = 6, happiness = 1, description = "Gojen biser iz bisernih ostrig." },
    black_pearl = { name = "Črni biser", pearlOysterBedCost = 1, silverCost = 1, time = 12, cost = 380, yield = 70, prestige = 12, happiness = 2, description = "Redki črni biser za plemiče." },
    silver_lipped_pearl = { name = "Srebrnousti biser", pearlOysterBedCost = 1, silverCost = 1, time = 16, cost = 800, yield = 85, prestige = 22, happiness = 4, description = "Srebrnousti biser za visoke plemiče." },
    royal_grand_pearl = { name = "Kraljevski veliki biser", pearlOysterBedCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 22, cost = 2400, yield = 100, prestige = 55, happiness = 11, description = "Veliki kraljevski biser z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Ostrigarska postaja", cost = { gold = 250, wood = 120, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    oyster_beds = { name = "Ostrigarske postelje", cost = { gold = 900, wood = 250, stone = 400, water = 10 }, upkeep = 22, qualityBonus = 18 },
    pearl_house = { name = "Biserna hiša", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, wood2 = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_oyster_atelier = { name = "Kraljevski atelje ostrigarstva", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
OysterFarmer.oysterBedStock = 22; OysterFarmer.pearlOysterBedStock = 14; OysterFarmer.silverStock = 8; OysterFarmer.goldStock = 6; OysterFarmer.jewelStock = 6
OysterFarmer.productStock = {}; OysterFarmer.buildings = {}; OysterFarmer.maker = nil; OysterFarmer.activeMaking = {}; OysterFarmer.totalProducts = 0; OysterFarmer.dayTimer = 0
function OysterFarmer.init() OysterFarmer.oysterBedStock=22; OysterFarmer.pearlOysterBedStock=14; OysterFarmer.silverStock=8; OysterFarmer.goldStock=6; OysterFarmer.jewelStock=6; OysterFarmer.productStock={}; OysterFarmer.buildings={}; OysterFarmer.maker=nil; OysterFarmer.activeMaking={}; OysterFarmer.totalProducts=0; OysterFarmer.dayTimer=0; print("[OysterFarmer] Royal Oyster Farmer System initialized (6 products, 4 buildings)") end
function OysterFarmer.hireMaker(n,s) s=s or math.random(50,90); local c=510+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; OysterFarmer.maker={name=n or ("Ostrigar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ostrigar najet: %s (spretnost: %d)",OysterFarmer.maker.name,s),"success") end; return true end
function OysterFarmer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function OysterFarmer.build(id) local ok,e=OysterFarmer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(OysterFarmer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function OysterFarmer.getQualityBonus() local b=0; for _,bd in ipairs(OysterFarmer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function OysterFarmer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.oysterBedCost and OysterFarmer.oysterBedStock<(d.oysterBedCost or 0) then return false,"Premalo ostrigarskih postelj" end; if d.pearlOysterBedCost and OysterFarmer.pearlOysterBedStock<(d.pearlOysterBedCost or 0) then return false,"Premalo bisernih postelj" end; if d.silverCost and OysterFarmer.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and OysterFarmer.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and OysterFarmer.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #OysterFarmer.buildings==0 then return false,"Potrebna delavnica" end; if not OysterFarmer.maker then return false,"Potreben ostrigar" end; return true end
function OysterFarmer.make(pt,qty) qty=qty or 1; local ok,e=OysterFarmer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.oysterBedCost then OysterFarmer.oysterBedStock=OysterFarmer.oysterBedStock-d.oysterBedCost*qty end; if d.pearlOysterBedCost then OysterFarmer.pearlOysterBedStock=OysterFarmer.pearlOysterBedStock-d.pearlOysterBedCost*qty end; if d.silverCost then OysterFarmer.silverStock=OysterFarmer.silverStock-d.silverCost*qty end; if d.goldCost then OysterFarmer.goldStock=OysterFarmer.goldStock-d.goldCost*qty end; if d.jewelCost then OysterFarmer.jewelStock=OysterFarmer.jewelStock-d.jewelCost*qty end; local t=d.time; if OysterFarmer.maker then t=math.max(1,t-math.floor(OysterFarmer.maker.skill/12)) end; table.insert(OysterFarmer.activeMaking,{id="oyster_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function OysterFarmer.completeMaking(m) local q=1.0+(OysterFarmer.getQualityBonus()/100); if OysterFarmer.maker then q=q+(OysterFarmer.maker.skill/150) end; q=math.min(2.5,q); OysterFarmer.productStock[m.productType]=(OysterFarmer.productStock[m.productType] or 0)+m.quantity; OysterFarmer.totalProducts=OysterFarmer.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if OysterFarmer.maker then OysterFarmer.maker.itemsMade=OysterFarmer.maker.itemsMade+m.quantity; if math.random()<0.25 then OysterFarmer.maker.skill=math.min(100,OysterFarmer.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ostriga/biser pridelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"oyster.completed",{productName=m.productName,yield=m.yield,prestige=m.prestige,happiness=m.happiness}) end end
function OysterFarmer.update(dt) if not _G.state then return end; OysterFarmer.dayTimer=OysterFarmer.dayTimer+dt; if OysterFarmer.dayTimer>=30 then OysterFarmer.dayTimer=0; for i=#OysterFarmer.activeMaking,1,-1 do local m=OysterFarmer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then OysterFarmer.completeMaking(m); table.remove(OysterFarmer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(OysterFarmer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if OysterFarmer.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function OysterFarmer.getStats() return {oysterBedStock=OysterFarmer.oysterBedStock,pearlOysterBedStock=OysterFarmer.pearlOysterBedStock,silverStock=OysterFarmer.silverStock,goldStock=OysterFarmer.goldStock,jewelStock=OysterFarmer.jewelStock,productStock=OysterFarmer.productStock,numBuildings=#OysterFarmer.buildings,hasMaker=OysterFarmer.maker~=nil,makerName=OysterFarmer.maker and OysterFarmer.maker.name or "—",makerSkill=OysterFarmer.maker and OysterFarmer.maker.skill or 0,activeMaking=#OysterFarmer.activeMaking,totalProducts=OysterFarmer.totalProducts} end
return OysterFarmer
